   397	    my $output = $self->capture_timed(65_536, $pdfinfo, $path);
   398	    my ($pages) = $output =~ /^Pages:\s*([0-9]+)\s*$/m;
   399	    defined($pages) && $pages >= 1 && $pages <= $self->max_pdf_pages()
   400	        or _fatal('unable to determine a supported PDF page count');
   401	    return int($pages);
   402	}
   403	
   404	sub validate_page_range {
   405	    my ($self, $range, $total_pages) = @_;
   406	    $range =~ /\A[0-9]+(?:-[0-9]+)?(?:,[0-9]+(?:-[0-9]+)?)*\z/
   407	        or _fatal('page range must be a comma-separated list such as 1-3,5');
   408	    for my $part (split /,/, $range) {
   409	        my ($first, $last) = split /-/, $part, 2;
   410	        $last //= $first;
   411	        $first >= 1 && $last >= $first && $last <= $total_pages
   412	            or _fatal('page range contains a page outside the source PDF');
   413	    }
   414	    return $range;
   415	}
