   417	sub prompt_page_range {
   418	    my ($self, $total_pages) = @_;
   419	    return $self->validate_page_range(
   420	        $self->prompt_line("Pages (1-$total_pages, for example 1-3,5): "),
   421	        $total_pages,
   422	    );
   423	}
   424	
   425	sub directory_has_file {
   426	    my ($self, $directory, $expression) = @_;
   427	    opendir my $dh, $directory or _fatal("cannot inspect output directory: $!");
   428	    while (my $entry = readdir $dh) {
   429	        next if $entry eq '.' || $entry eq '..';
   430	        my $path = "$directory/$entry";
   431	        if (-f $path && !-l $path && $entry =~ $expression) {
   432	            closedir $dh;
   433	            return 1;
   434	        }
   435	    }
   436	    closedir $dh or _fatal("cannot close output directory: $!");
   437	    return 0;
   438	}
