    10	
    11	sub log_msg {
    12	    my ($level, $message) = @_;
    13	    my %priority = (
    14	        info    => LOG_INFO,
    15	        warning => LOG_WARNING,
    16	        error   => LOG_ERR,
    17	    );
    18	    $level = exists $priority{$level} ? $level : 'error';
    19	    $message = q{} if !defined $message;
    20	    $message =~ s/[\r\n]+/ /g;
    21	    $message =~ s/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/?/g;
    22	    $message = substr($message, 0, 2048);
    23	    return if !eval {
    24	        openlog('labwc-digital-assets', 'pid,nowait', LOG_USER);
    25	        syslog($priority{$level}, '%s', $message);
    26	        closelog();
    27	        1;
    28	    };
    29	}
