== managed unit content ==
--- d-i/forky/hooks/role/desktop/target/etc/systemd/system/managed-external-software-download.service ---
[Unit]
Description=Download managed external desktop application updates
Documentation=man:systemd.service(5)
Wants=network-online.target
After=network-online.target apt-daily.service apt-daily-upgrade.service
RequiresMountsFor=/usr /var/lib/software
ConditionArchitecture=x86-64
ConditionFileIsExecutable=/usr/local/sbin/managed-external-software-update

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/managed-external-software-update --download-only
TimeoutStartSec=60min
