        return (1, 'extract');
    };
    eval {
        $self->_normalize_tree($staged);
        ExternalSoftware::Servicing::Atomic->write_text(
            "$staged/.managed-release",
            join(
                q{},
                "version=$pending->{version}\n",
                "archive_sha256=$pending->{sha256}\n",
                "architecture=amd64\n",
            ),
            0644,
        );
        1;
    } or do {
        remove_tree($staged, { safe => 1 });
        return (1, 'publish');
    };

